import { Slider } from "@mui/material";
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import data from "../data.json";
import righttickImg from "../image/rightTick.jpg";
import wrongTickImg from "../image/wrongTick.jpg";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import ReactGA from "react-ga4";
import Swal from "sweetalert2";
import { FormControl, MenuItem, Select } from "@mui/material";
import { motion } from "framer-motion";

const Level1MidContent = () => {
  const [pageName, setpageName] = useState("Level-1");
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const parse = require("html-react-parser").default;
  let [randomNumberArray, setRandomNumberArray] = useState([0]);
  let [randomNumber, setRandomNumber] = useState(0);
  let navigate = useNavigate();
  const [level, setLevel] = useState("Level 1");

  const handleChange = (event) => {
    setLevel(event.target.value);
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level1/level2");
        break;
    }
  };

  const handleClick = (value) => {
    if (data.level1[randomNumber].CorrectAnswer === value) {
      Swal.fire({
        title: "Correct!",
        customClass: {
          title: "green-text",
          htmlContainer: "green-text",
        },
      }).then((result) => {
        if (result.isConfirmed) {
          setTimeout(handleNext, 500);
        }
      });
    } else {
      Swal.fire({
        title: "Wrong answer!",
        text: data.level1[randomNumber].feedback,
        customClass: {
          title: "red-text",
          htmlContainer: "red-text",
        },
      });
    }
  };

  const handleNext = () => {
    randomNumber = Math.floor(Math.random() * data.level1.length);
    if (randomNumberArray.length !== 10) {
      if (randomNumberArray.includes(randomNumber)) {
        handleNext();
      } else {
        setRandomNumberArray((prevState) => [...prevState, randomNumber]);
        setRandomNumber(randomNumber);
      }
    } else {
      Swal.fire({
        title: `You have successfully attempted 10 sentences!`,
        showClass: {
          popup: "animate__animated animate__fadeInDown",
        },
        hideClass: {
          popup: "animate__animated animate__fadeOutUp",
        },
        customClass: {
          title: "completeion-text",
          htmlContainer: "completeion-text",
        },
        confirmButtonText: "Proceed to Level-2",
      }).then((result) => {
        if (result.isConfirmed) {
          navigate("/launchpage/englishactivity/level1/level2");
        }
      });
    }

    ReactGA.event({
      action: `Eng31|Indefinite pronoun|Clicked on "right/wrong" button of level-1`,
      category: `Eng31|right/wrong button clicked`,
      label: `Eng31|Clicked on right/wrong button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "right/wrong",
      "Clicked",
      "Clicked to move to the next sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
          }}
        >
          <div className="row mb-3 sticky-top">
            <div className="d-flex justify-content-end">
              <FormControl size="small">
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level} // Step 3: Set the value prop
                  onChange={handleChange}
                  sx={{
                    bgcolor: "green", // Set background color
                    borderRadius: "8px", // Set border radius
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green", // Set border color if needed
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">Level 1</MenuItem>
                  <MenuItem value="Level 2">Level 2</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>
          <div className="row mb-3">
            <div className="d-flex align-items-center">
              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={10}
                value={randomNumberArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />

              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomNumberArray.length}/{10}
              </span>
            </div>
          </div>
          <div className="row mb-3">
            <div className="col-sm-12 d-flex flex-column align-items-center justify-content-end">
              <div
                className="d-flex justify-content-center align-items-center image-container"
                style={{
                  background: "#FFFFFF",
                  height: "250px",
                  width: "250px",
                  borderRadius: "13px",
                  boxShadow: "0px 4px 7px #00000029",
                  margin: "0 auto",
                  overflow: "hidden",
                }}
              >
                <div className="flip-box">
                  <div className="flip-box-inner">
                    <div className="flip-box-front">
                      <img
                        className="img-fluid"
                        src={require(`../image/${data.level1[randomNumber].imgSrc}`)}
                        alt="Current Image"
                      />
                    </div>
                    <div className="flip-box-back">
                      <div className="text-muted">
                        {parse(data.level1[randomNumber].sentence)}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div className="row mb-3">
            <div className="d-flex justify-content-around">
              <div>
                <motion.div
                  whileHover={{ scale: 1.3 }} // Scale up the button on hover
                  whileTap={{ scale: 0.9 }} // Scale down the button on tap
                  style={{ display: "inline-block" }}
                >
                  <button>
                    <img
                      onClick={() => handleClick("Correct")}
                      src={righttickImg}
                      alt="image not found"
                    />
                  </button>
                </motion.div>
              </div>
              <div>
                <motion.div
                  whileHover={{ scale: 1.3 }} // Scale up the button on hover
                  whileTap={{ scale: 0.9 }} // Scale down the button on tap
                  style={{ display: "inline-block" }}
                >
                  <button>
                    <img
                      onClick={() => handleClick("Incorrect")}
                      src={wrongTickImg}
                      alt="image not found"
                    />
                  </button>
                </motion.div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "13px 13px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            Instructions
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", lineHeight: "30px" }}>
            <ul>
              <li>Click and hold on the picture.</li>
              <li>Read the sentence carefully.</li>
              <li>
                If the indefinite pronoun matches with the image, then click on
                the correct tick; otherwise, click on the wrong tick.
              </li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level1MidContent;
