import { Button, Slider, FormControl, MenuItem, Select } from "@mui/material";
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import data from "../data.json";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import ReactGA from "react-ga4";
import Swal from "sweetalert2";
import { DragDropContainer, DropTarget } from "react-drag-drop-container";

const Level2MidContent = () => {
  const [pageName] = useState("Level-1");
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [randomNumberArray, setRandomNumberArray] = useState([0]);
  const [randomNumber, setRandomNumber] = useState(0);
  const navigate = useNavigate();
  const [level, setLevel] = useState("Level 2");
  const [formedSentenceArray, setFormedSentenceArray] = useState([]);
  let [nextDisabled, setNextDisabled] = useState(true);
  let [trialArrayForNextDisabled, seTtrialArrayForNextDisabled] = useState([]);

  const handleChange = (event) => {
    const selectedLevel = event.target.value;
    setLevel(selectedLevel);
    switch (selectedLevel) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level1/level2");
        break;
    }
  };

  const handleNext = () => {
    setNextDisabled(true);
    seTtrialArrayForNextDisabled([]);
    // Reset the background color and content of all drop targets
    for (let i = 0; i < 3; i++) {
      const dropTarget = document.getElementById(`drop_${i}`);
      if (dropTarget) {
        dropTarget.style.background = ""; // Reset background color
        dropTarget.innerHTML = ""; // Clear the content
      }
    }

    setFormedSentenceArray([]);
    let newRandomNumber = Math.floor(Math.random() * data.level2.length);
    if (randomNumberArray.length !== data.level2.length) {
      if (randomNumberArray.includes(newRandomNumber)) {
        handleNext();
      } else {
        setRandomNumberArray((prevState) => [...prevState, newRandomNumber]);
        setRandomNumber(newRandomNumber);
      }
    } else {
      Swal.fire({
        title: `You have successfully attempted all sets of questions!`,
        showClass: { popup: "animate__animated animate__fadeInDown" },
        hideClass: { popup: "animate__animated animate__fadeOutUp" },
        customClass: {
          title: "completion-text",
          htmlContainer: "completion-text",
        },
        confirmButtonText: "Restart",
      }).then((result) => {
        if (result.isConfirmed) {
          navigate("/");
        }
      });
    }

    ReactGA.event({
      action: `Eng31|Indefinite pronoun|Clicked on "right/wrong" button of level-1`,
      category: `Eng31|right/wrong button clicked`,
      label: `Eng31|Clicked on right/wrong button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "right/wrong",
      "Clicked",
      "Clicked to move to the next sentence",
      [{ input: "", answer: "", result: "" }],
      [{ popuptype: "", popuptext: "" }],
      [{ hint: "" }]
    );
  };

  const handleDrop = (e, index) => {
    const newWord = e.dragData.word;
    const updatedArray = [...formedSentenceArray];
    const hiddenWordArray = data.level2[randomNumber].hiddenwordArray;
    updatedArray[index] = newWord;
    document.getElementById(`drop_${index}`).innerHTML = newWord;
    setFormedSentenceArray(updatedArray);
    if (updatedArray[index] !== hiddenWordArray[index]) {
      Swal.fire({
        title: "Incorrect!",
        text: `${data.level2[randomNumber].explanation[newWord]}`,
        customClass: {
          title: "red-text",
          htmlContainer: "red-text",
        },
      });
      document.getElementById(`drop_${index}`).style.backgroundColor = "red";
    } else {
      document.getElementById(`drop_${index}`).style.backgroundColor = "green";
      trialArrayForNextDisabled[index] = newWord;
    }

    //checking is there any droppable position red in color to enable/disable next button.
    const filteredArray = trialArrayForNextDisabled.filter((item) => item);
    if (filteredArray.length !== 3) {
      return; // Exit if there are not exactly 3 truthy elements
    } else {
      setNextDisabled(false);
      console.log("Next is enabled, filtered array:", filteredArray);
    }
  };

  const handleSkip = () => {
    handleNext();
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex flex-column align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
          }}
        >
          <div className="row mb-3 sticky-top">
            <div className="d-flex justify-content-end">
              <FormControl size="small">
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: "8px",
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">Level 1</MenuItem>
                  <MenuItem value="Level 2">Level 2</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>
          <div className="row mb-3">
            <div className="d-flex align-items-center">
              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={data.level2.length}
                value={randomNumberArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomNumberArray.length}/{data.level2.length}
              </span>
            </div>
          </div>
          <div className="row mb-3">
            <div
              className="d-flex flex-column"
              style={{
                background:
                  "linear-gradient(268deg, rgb(253, 189, 35) 0%, rgb(247, 185, 78) 100%)",
                borderRadius: "10px",
                boxShadow: "rgba(0, 0, 0, 0.16) 0px 3px 6px",
                opacity: "1",
                padding: "2%",
                fontWeight: "bolder",
              }}
            >
              <div className="d-flex flex-wrap justify-content-center flex-grow-1 align-items-center">
                {data.level2[randomNumber].optionWords.map((item, index) => (
                  <DragDropContainer
                    key={index}
                    targetKey="item"
                    dragData={{ word: item }}
                  >
                    <div className="col-6 col-md-4 col-lg-3 p-2">
                      <div className="item-card">{item}</div>
                    </div>
                  </DragDropContainer>
                ))}
              </div>
            </div>
          </div>
          <div className="row mb-3">
            <div
              style={{
                background:
                  "linear-gradient(268deg, rgb(253, 189, 35) 0%, rgb(247, 185, 78) 100%)",
                borderRadius: "10px",
                boxShadow: "rgba(0, 0, 0, 0.16) 0px 3px 6px",
                opacity: "1",
                padding: "2%",
                fontWeight: "bolder",
                overflow: "auto",
              }}
            >
              <div className="text-center">Sentences</div>
              <hr
                style={{
                  color: "white",
                  marginTop: "5px",
                  marginBottom: "5px",
                }}
              />
              {data.level2[randomNumber].sentArray.map((item, index) => (
                <div key={index} className="mb-2">
                  <div className="d-flex align-items-center">
                    {index + 1}. &nbsp;
                    {item.split(" ").map((sentword, wordindex) =>
                      data.level2[randomNumber].hiddenwordArray.includes(
                        sentword
                      ) ? (
                        <DropTarget
                          targetKey="item"
                          onHit={(e) => handleDrop(e, index)}
                          key={wordindex}
                        >
                          <span className="item-card-copy" id={`drop_${index}`}>
                            &nbsp;
                          </span>
                        </DropTarget>
                      ) : (
                        <span key={wordindex} className="d-inline-block">
                          {sentword}&nbsp;
                        </span>
                      )
                    )}
                  </div>
                  <hr
                    style={{
                      color: "white",
                      marginTop: "5px",
                      marginBottom: "5px",
                    }}
                  />
                </div>
              ))}
            </div>
          </div>

          <div className="row mb-3">
            <div className="d-flex justify-content-around">
              <Button variant="contained" onClick={handleSkip}>
                SKIP
              </Button>
              <Button
                disabled={nextDisabled}
                variant="contained"
                onClick={handleNext}
              >
                {randomNumberArray.length === 4 ? "FINISH" : "NEXT"}
              </Button>
            </div>
          </div>
        </div>
      </div>
      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "13px 13px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            Instructions
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", lineHeight: "30px" }}>
            <ul>
              <li>
                Drag and drop the correct indefinite pronoun at its correct
                place.
              </li>
              <li>
                Click on the "NEXT" button to get the new set of sentences.
              </li>
              <li>Click on the "SKIP" button to skip the current set of sentences.</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level2MidContent;
